<template>
  <div class="space-y-6">
    <RouterLink to="/campanhas" class="focus-ring rounded text-sm font-semibold">← Voltar às campanhas</RouterLink>
    <header class="flex flex-wrap items-end justify-between gap-4"><div><p class="text-xs font-bold uppercase tracking-widest text-sage-muted">Prévia da esteira · dados fictícios</p><h1 class="mt-2 text-3xl font-extrabold tracking-tight">Campanha de exemplo</h1><p class="mt-3 text-sm text-sage-muted">Explore as responsabilidades de cada perfil sem alterar uma campanha real.</p></div><button v-if="access.role.value === 'ADMINISTRADOR'" type="button" class="focus-ring rounded-full border border-sage-border-dark bg-white px-4 py-2 text-sm font-semibold" @click="resetOpen = true">Reiniciar exemplo</button></header>
    <section class="rounded-2xl border border-warning-border bg-warning-bg p-4 text-sm leading-6 text-warning-text"><strong>Prévia navegável.</strong> Envios, aprovações e resultados abaixo são exemplos locais. Para testar a passagem entre responsáveis, saia e entre com outra conta de demonstração na mesma aba. O exemplo é retomado no ponto em que parou.</section>
    <section class="rounded-2xl bg-white p-5"><div class="flex flex-wrap items-center justify-between gap-3"><div><p class="text-xs uppercase tracking-widest text-sage-muted">Situação do exemplo</p><h2 class="mt-2 text-lg font-extrabold">{{ statusLabel }}</h2></div><span class="rounded-full bg-sage-pill px-3 py-1.5 text-xs font-semibold">Revisão {{ workflow.revision }}</span></div><p class="mt-3 text-sm text-sage-muted">{{ workflow.status === 'PUBLISHED' ? 'Fluxo demonstrativo concluído. Nenhuma campanha real foi publicada.' : 'Próxima ação: ' + currentOwner.owner + ' · etapa ' + workflow.step }}</p><button v-if="viewed !== workflow.step" class="focus-ring mt-3 rounded text-sm font-bold underline" @click="selectStep(currentOwner.key)">Voltar à etapa pendente →</button></section>
    <CampaignStepNav :steps="STEP_RESPONSIBILITIES" :current-step="viewedKey" :current-step-number="viewed" :reached-step="workflow.reached" @select="selectStep" />
    <CampaignStageAccess :step="viewedKey" :reason="viewed === workflow.step ? workflow.reason : ''" :available="isCurrent" />
    <p v-if="!isCurrent" class="rounded-xl bg-sage-light p-4 text-sm text-sage-subtle">{{ workflow.status === 'PUBLISHED' ? 'Exemplo concluído, disponível somente para consulta.' : 'Esta etapa já foi encaminhada. Os dados podem ser consultados; as ações estão na etapa pendente.' }}</p>
    <section class="rounded-[24px] bg-white p-6 sm:p-8">
      <template v-if="viewed === 1"><h2 class="text-xl font-extrabold">Proposta da campanha</h2><fieldset :disabled="!canAct" class="mt-6 space-y-5 disabled:opacity-75"><div><label for="preview-title" class="mb-2 block text-sm font-semibold">Título</label><input id="preview-title" :value="workflow.campaign.title" maxlength="120" class="focus-ring w-full rounded-xl border border-sage-border-dark p-3 text-sm" @input="edit('title', $event.target.value)" /></div><div><label for="preview-description" class="mb-2 block text-sm font-semibold">Descrição</label><textarea id="preview-description" :value="workflow.campaign.description" rows="4" class="focus-ring w-full rounded-xl border border-sage-border-dark p-3 text-sm" @input="edit('description', $event.target.value)"></textarea></div></fieldset><p class="mt-4 text-xs text-sage-muted">Alterar a proposta invalida a conferência e a simulação anteriores deste exemplo.</p></template>
      <template v-else-if="viewed === 2"><h2 class="text-xl font-extrabold">Conferência das regras</h2><p class="mt-3 text-sm leading-6 text-sage-muted">{{ workflow.campaign.description }}</p><div class="mt-6"><label for="preview-rate" class="mb-2 block text-sm font-semibold">Taxa final da regra (%)</label><input id="preview-rate" :value="workflow.campaign.rate" :disabled="!canAct" inputmode="decimal" class="focus-ring w-full max-w-xs rounded-xl border border-sage-border-dark p-3 text-sm disabled:bg-sage-light" @input="edit('rate', $event.target.value)" /></div><p class="mt-4 text-sm" :class="workflow.codeApprovedRevision === workflow.revision ? 'text-success-dark' : 'text-warning-text'">{{ workflow.codeApprovedRevision === workflow.revision ? 'Conferência de exemplo atualizada.' : 'Aguardando conferência do responsável por código.' }}</p><details class="mt-5 rounded-2xl bg-brand-dark p-5 text-white"><summary class="focus-ring cursor-pointer rounded font-bold text-brand">Visualizar código de exemplo</summary><p class="mt-3 text-xs text-white/70">Somente para demonstrar a revisão. Não será executado.</p><pre class="mt-4 overflow-x-auto text-xs leading-6 text-brand"><code>{{ code }}</code></pre></details></template>
      <template v-else-if="viewed === 3"><h2 class="text-xl font-extrabold">Simulação de exemplo</h2><p class="mt-3 text-sm text-sage-muted">Referência fictícia: julho de 2025. Os valores abaixo servem somente para testar o fluxo de acesso.</p><div class="mt-6"><label for="preview-budget" class="mb-2 block text-sm font-semibold">Orçamento de exemplo (R$)</label><input id="preview-budget" :value="workflow.campaign.budget" :disabled="!canAct" inputmode="decimal" class="focus-ring w-full max-w-xs rounded-xl border border-sage-border-dark p-3 text-sm disabled:bg-sage-light" @input="edit('budget', $event.target.value)" /></div><p class="mt-4 rounded-xl bg-sage-light p-3 text-sm">{{ simulationCurrent ? 'Resultado demonstrativo atual. Pronto para encaminhar à revisão.' : 'A simulação precisa ser refeita após mudanças. O resultado anterior não está válido para encaminhamento.' }}</p><div v-if="simulationCurrent" class="mt-5 grid gap-4 sm:grid-cols-3"><div v-for="metric in metrics" :key="metric.label" class="rounded-2xl border border-sage-border p-4"><p class="text-xs text-sage-muted">{{ metric.label }}</p><p class="mt-2 text-xl font-bold">{{ metric.value }}</p></div></div><button v-if="canAct" class="focus-ring mt-6 rounded-full border border-sage-border-dark px-5 py-3 text-sm font-bold hover:bg-sage-light" @click="simulate">{{ simulationCurrent ? 'Refazer exemplo de simulação' : 'Gerar exemplo de simulação' }}</button></template>
      <template v-else><h2 class="text-xl font-extrabold">Conferência gerencial</h2><p class="mt-3 text-sm leading-6 text-sage-muted">Confira a proposta e a situação das etapas anteriores antes de confirmar ou devolver o exemplo.</p><dl class="mt-6 grid gap-5 text-sm sm:grid-cols-2"><div><dt class="text-sage-muted">Campanha</dt><dd class="mt-1 font-semibold">{{ workflow.campaign.title }}</dd></div><div><dt class="text-sage-muted">Taxa final</dt><dd class="mt-1 font-semibold">{{ workflow.campaign.rate }}%</dd></div><div><dt class="text-sage-muted">Conferência do código</dt><dd class="mt-1 font-semibold">{{ workflow.codeApprovedRevision === workflow.revision ? 'Atualizada no exemplo' : 'Pendente' }}</dd></div><div><dt class="text-sage-muted">Simulação</dt><dd class="mt-1 font-semibold">{{ simulationCurrent ? 'Atualizada no exemplo' : 'Pendente' }}</dd></div></dl></template>
    </section>
    <p v-if="error" role="alert" class="rounded-xl bg-danger-bg p-4 text-sm text-danger-dark">{{ error }}</p>
    <footer v-if="canAct" class="flex flex-wrap justify-end gap-3 border-t border-sage-border pt-5"><button v-if="[2, 4].includes(viewed)" class="focus-ring rounded-full border border-sage-border-dark bg-white px-5 py-3 text-sm font-semibold" @click="returnReason = ''; returnOpen = true">Devolver para correção</button><button :disabled="viewed === 3 && !simulationCurrent" class="focus-ring rounded-full bg-brand px-5 py-3 text-sm font-bold hover:bg-brand-hover disabled:opacity-50" @click="advance">{{ ['Enviar para conferência do código →', 'Confirmar conferência e encaminhar →', 'Encaminhar ao gerente →', 'Concluir aprovação de exemplo'][viewed - 1] }}</button></footer>
    <details v-if="workflow.history.length" class="rounded-2xl bg-white p-5"><summary class="focus-ring cursor-pointer rounded font-bold">Histórico do exemplo · {{ workflow.history.length }} ações</summary><ol class="mt-5 space-y-4"><li v-for="(event, index) in workflow.history" :key="index" class="border-l-2 border-sage-border pl-4 text-sm"><p class="font-semibold">{{ event.name }} · {{ roleLabel(event.role) }}</p><p class="mt-1 text-sage-muted">{{ event.action === 'return' ? 'Devolução' : 'Encaminhamento' }} · etapa {{ event.from }} → {{ event.to }}</p><p v-if="event.reason" class="mt-1">{{ event.reason }}</p></li></ol></details>
    <CampaignLifecycleDialog :open="returnOpen" title="Devolver para correção" confirm-label="Confirmar devolução de exemplo" :disabled="!returnReason.trim()" @cancel="returnOpen = false" @confirm="sendBack"><label for="preview-return" class="font-semibold">Motivo da devolução *</label><textarea id="preview-return" v-model="returnReason" rows="4" maxlength="1000" class="focus-ring mt-2 w-full rounded-xl border border-sage-border p-3" placeholder="Explique o que precisa ser corrigido."></textarea><p class="mt-3 text-sage-muted">O motivo ficará visível para o responsável pela correção.</p></CampaignLifecycleDialog>
    <CampaignLifecycleDialog :open="resetOpen" title="Reiniciar o exemplo?" confirm-label="Reiniciar exemplo" @cancel="resetOpen = false" @confirm="reset"><p>Somente os dados fictícios desta esteira serão reiniciados.</p></CampaignLifecycleDialog>
  </div>
</template>
<script setup>
import { computed, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { STEP_RESPONSIBILITIES } from '@/services/accessPolicy'
import { useAccessPolicy } from '@/services/useAccessPolicy'
import { useAccountStore } from '@/stores/accountStore'
import { roleLabel } from '@/services/accountPreview'
import { newWorkflowPreview, restoreWorkflowPreview, persistWorkflowPreview, previewCanAct, transitionPreview, editPreview, simulatePreview } from '@/services/workflowPreview'
import CampaignStepNav from '@/components/common/CampaignStepNav.vue'
import CampaignStageAccess from '@/components/campaigns/CampaignStageAccess.vue'
import CampaignLifecycleDialog from '@/components/campaigns/CampaignLifecycleDialog.vue'
const route = useRoute(), router = useRouter(), access = useAccessPolicy(), account = useAccountStore()
let storage; try { storage = window.sessionStorage } catch {}
const workflow = ref(restoreWorkflowPreview(storage)), viewed = ref(workflow.value.step), error = ref(''), returnOpen = ref(false), returnReason = ref(''), resetOpen = ref(false)
const viewedKey = computed(() => STEP_RESPONSIBILITIES[viewed.value - 1].key)
const currentOwner = computed(() => STEP_RESPONSIBILITIES[workflow.value.step - 1])
const isCurrent = computed(() => viewed.value === workflow.value.step && workflow.value.status !== 'PUBLISHED')
const canAct = computed(() => isCurrent.value && previewCanAct(access.role.value, workflow.value))
const simulationCurrent = computed(() => workflow.value.simulationRevision === workflow.value.revision && workflow.value.codeApprovedRevision === workflow.value.revision)
const statusLabel = computed(() => ({ EDITING: 'Proposta em preparação', WAITING_CODE: 'Aguardando analista de código', WAITING_SIMULATION: 'Aguardando analista de negócios', WAITING_MANAGER: 'Aguardando gerente', RETURNED: 'Devolvida para correção', PUBLISHED: 'Exemplo de aprovação concluído' })[workflow.value.status])
const money = value => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(value)
const metrics = computed(() => { const proposed = 10000 * Number(workflow.value.campaign.rate.replace(',', '.')) / 100; return [{ label: 'Vendas fictícias de referência', value: money(10000) }, { label: 'Comissão base de exemplo (2,5%)', value: money(250) }, { label: 'Comissão proposta de exemplo', value: money(proposed) }] })
const code = computed(() => `# Exemplo visual — não executado\nfrom decimal import Decimal, ROUND_HALF_UP\n\ndef exemplo(valor_venda):\n    taxa = Decimal('${workflow.value.campaign.rate.replace(',', '.')}') / 100\n    return (Decimal(str(valor_venda)) * taxa).quantize(\n        Decimal('0.01'), rounding=ROUND_HALF_UP\n    )`)
watch(() => route.query.etapa, value => { const step = STEP_RESPONSIBILITIES.find(s => s.key === value)?.number; viewed.value = step && step <= workflow.value.reached ? step : workflow.value.step; const allowed = STEP_RESPONSIBILITIES[viewed.value - 1].key; if (value !== allowed) router.replace({ query: { etapa: allowed } }) }, { immediate: true })
function selectStep(key) { const step = STEP_RESPONSIBILITIES.find(s => s.key === key); if (step && step.number <= workflow.value.reached) router.replace({ query: { etapa: key } }) }
function commit(next) { workflow.value = next; persistWorkflowPreview(storage, next); error.value = '' }
function edit(field, value) { if (!canAct.value) return; try { commit(editPreview(workflow.value, field, value, access.role.value)) } catch (e) { error.value = e.message } }
function action(action, reason = '') { if (!canAct.value) return false; try { commit(transitionPreview(workflow.value, { action, reason, role: access.role.value, name: account.user.name })); viewed.value = workflow.value.step; router.replace({ query: { etapa: currentOwner.value.key } }); return true } catch (e) { error.value = e.message; return false } }
function advance() { action('advance') }
function sendBack() { if (action('return', returnReason.value)) returnOpen.value = false }
function simulate() { if (!canAct.value) return; try { commit(simulatePreview(workflow.value, access.role.value)) } catch (e) { error.value = e.message } }
function reset() { if (access.role.value !== 'ADMINISTRADOR') return; commit(newWorkflowPreview()); viewed.value = 1; resetOpen.value = false; router.replace({ query: { etapa: 'dados' } }) }
</script>
